<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { systemApi, type Department, type Role, type UserRow } from '@/api/system'

const rows=ref<UserRow[]>([]), departments=ref<Department[]>([]), roles=ref<Role[]>([]), loading=ref(false), visible=ref(false), passwordVisible=ref(false)
const editingId=ref<number|null>(null)
const form=reactive({username:'',password:'',displayName:'',deptId:null as number|null,status:'ENABLED',version:0,roleIds:[] as number[]})
const reset=reactive({id:0,password:'adimin'})
async function load(){loading.value=true;try{[rows.value,departments.value,roles.value]=await Promise.all([systemApi.users(),systemApi.departments(),systemApi.roles()])}finally{loading.value=false}}
function create(){editingId.value=null;Object.assign(form,{username:'',password:'',displayName:'',deptId:null,status:'ENABLED',version:0,roleIds:[]});visible.value=true}
async function edit(row:UserRow){editingId.value=row.id;Object.assign(form,{username:row.username,password:'',displayName:row.displayName,deptId:row.deptId,status:row.status,version:row.version,roleIds:await systemApi.userRoles(row.id)});visible.value=true}
async function save(){if(!form.displayName||(!editingId.value&&(!form.username||form.password.length<6))){ElMessage.warning('请完整填写用户信息');return}if(editingId.value)await systemApi.updateUser(editingId.value,{displayName:form.displayName,deptId:form.deptId,status:form.status,version:form.version,roleIds:form.roleIds});else await systemApi.createUser(form);visible.value=false;ElMessage.success('保存成功');await load()}
async function toggle(row:UserRow){await systemApi.userStatus(row.id,row.status==='ENABLED'?'DISABLED':'ENABLED');ElMessage.success('状态已更新');await load()}
function openReset(row:UserRow){reset.id=row.id;reset.password='adimin';passwordVisible.value=true}
async function savePassword(){await systemApi.resetPassword(reset.id,reset.password);passwordVisible.value=false;ElMessage.success('密码已重置')}
async function remove(row:UserRow){await ElMessageBox.confirm(`确定删除用户“${row.displayName}”吗？`,'删除确认',{type:'warning'});await systemApi.deleteUser(row.id);ElMessage.success('已删除');await load()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p>IDENTITY</p><h1>用户管理</h1></div><el-button type="primary" @click="create">新增用户</el-button></div><div class="content-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="username" label="用户名"/><el-table-column prop="displayName" label="姓名"/><el-table-column prop="departmentName" label="部门"/><el-table-column prop="roleNames" label="角色"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='ENABLED'?'success':'info'">{{s.row.status==='ENABLED'?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="425"><template #default="s"><div class="system-action-group"><el-button class="system-action system-edit-action" @click="edit(s.row)">编辑</el-button><el-button class="system-action system-toggle-action" @click="toggle(s.row)">{{s.row.status==='ENABLED'?'停用':'启用'}}</el-button><el-button class="system-action system-reset-action" @click="openReset(s.row)">重置密码</el-button><el-button class="system-action system-delete-action" @click="remove(s.row)">删除</el-button></div></template></el-table-column></el-table></div>
<el-dialog v-model="visible" :title="editingId?'编辑用户':'新增用户'" width="560px"><el-form label-width="90px"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="Boolean(editingId)"/></el-form-item><el-form-item v-if="!editingId" label="初始密码"><el-input v-model="form.password" show-password/></el-form-item><el-form-item label="姓名"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="部门"><el-select v-model="form.deptId" clearable style="width:100%"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="角色"><el-select v-model="form.roleIds" multiple style="width:100%"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="ENABLED">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="passwordVisible" title="重置密码" width="420px"><el-input v-model="reset.password" show-password placeholder="至少6位"/><template #footer><el-button @click="passwordVisible=false">取消</el-button><el-button type="primary" @click="savePassword">确认重置</el-button></template></el-dialog></section></template>
